def overlap_size(a_start: int, a_end: int, b_start: int, b_end: int) -> int:
    if a_start < 0 or a_start > 255 or a_end < 0 or a_end > 255 or b_start < 0 or b_start > 255 or b_end < 0 or b_end > 255:
        return -1
    if a_end < a_start or b_end < b_start:
        return -1
    lo = a_start if a_start > b_start else b_start
    hi = a_end if a_end < b_end else b_end
    if hi > lo:
        return hi - lo
    return 0
